CREATE EXTENSION IF NOT EXISTS "uuid-ossp";CREATE TYPE TASK_STATUS AS ENUM ('To Do', 'In Progress', 'Done');CREATE TYPE TASK_PRIORITY AS ENUM ('Low', 'Medium', 'High');CREATE TABLE users (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), email VARCHAR(255) UNIQUE NOT NULL, hashed_password VARCHAR(255) NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);CREATE INDEX idx_users_email ON users (email);CREATE TABLE projects (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL, name VARCHAR(255) NOT NULL, description TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);CREATE INDEX idx_projects_user_id ON projects (user_id);CREATE TABLE tasks (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), project_id UUID NOT NULL, user_id UUID NOT NULL, title VARCHAR(255) NOT NULL, description TEXT, status TASK_STATUS DEFAULT 'To Do' NOT NULL, priority TASK_PRIORITY DEFAULT 'Medium' NOT NULL, due_date TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);CREATE INDEX idx_tasks_project_id ON tasks (project_id);CREATE INDEX idx_tasks_user_id ON tasks (user_id);CREATE INDEX idx_tasks_status ON tasks (status);CREATE INDEX idx_tasks_priority ON tasks (priority);CREATE INDEX idx_tasks_due_date ON tasks (due_date);